corrected_code:
const loadProject = async (req, res, next) => {
  const project = await ProjectModel.findOne({ _id: req.params.projectId, ownerId: req.user.id });
  if (!project) return res.status(403).json({ error: 'Access denied to target project' });
  res.locals.project = project;
  next();
};

app.patch('/api/projects/:projectId', authenticateUser, loadProject, async (req, res) => {
  Object.assign(res.locals.project, req.body);
  await res.locals.project.save();
  res.json(res.locals.project);
});
